 window.addEventListener('bell:render',()=>{ $('#previewSemester').value=semester;$('#previewTeacherMenu').classList.toggle('hidden',!teacherReady||isPublicView());$('#homeContext').classList.toggle('on-home',view==='welcome');$('.title-row').classList.toggle('hidden',view==='welcome');$('#contextCaption').textContent=view==='welcome'?'YOUR CLASSROOM':'BROWSING CLASS';$('.footer').innerHTML='<span>Miss Bell’s English Club</span><span>A happy little place to learn. ✧</span>'; });
