// Design preview additions. No production database connections.
let attentionFilter='all';
function updatedLabel(item){const d=item.updatedAt||item.date;return d?`<small class="updated-label">Updated ${escapeHtml(new Date(d.length===10?d+'T00:00:00+07:00':d).toLocaleDateString('en-GB',{timeZone:'Asia/Jakarta',day:'numeric',month:'short'}))}</small>`:'';}
function attentionControls(){return `<div class="board-filter"><span class="small-caps">NEEDS ATTENTION · TEACHER ONLY</span><label>Show <select id="attentionFilter"><option value="all">All attention items</option><option value="blanks">Blank scores</option><option value="low">Below target / remedial</option><option value="missing">Overdue assignments</option></select></label></div>`;}
function attentionRows(all){const rows=students().map(student=>{const r=all.find(x=>x.student.id===student.id)||{student,low:[],missing:[]};const blanks=tests().filter(t=>finalDaily(data,student.id,t.id)===null).map(t=>`LM ${t.lm} K${t.competency}`);for(const [type,label] of [['mid','Midterm'],['end','End-of-semester']])if(finalMain(data,student.id,semester,type)===null)blanks.push(label);return {...r,blanks};});return rows.filter(r=>attentionFilter==='all'?r.blanks.length||r.low.length||r.missing.length:attentionFilter==='blanks'?r.blanks.length:attentionFilter==='low'?r.low.length:r.missing.length);}
function weekBounds(){const today=localToday(),d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));const start=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()+6);return {start,end:d.toISOString().slice(0,10)};}
function classContent(field){return (data[field]||[]).filter(x=>x.classId===classId&&x.semester===semester);}
function weekContent(field){const {start}=weekBounds();return classContent(field).filter(x=>x.weekStart<=start&&isPublished(x)).sort((a,b)=>b.weekStart.localeCompare(a.weekStart))[0];}
function weeklyPlan(){const {start,end}=weekBounds(),plan=classContent('learningPlans').filter(x=>x.weekStart===start&&isPublished(x)).at(-1),list=calendarItems(data,semester,classId).filter(isPublished).filter(x=>x.date>=start&&x.date<=end);return `<section class="panel weekly-plan"><div class="panelhead"><div><span class="small-caps">THIS WEEK IN ENGLISH</span><h2>Weekly Learning Plan</h2><p>${escapeHtml(dateLabel(start))} – ${escapeHtml(dateLabel(end))} · Class ${classId} · Semester ${semester}</p></div>${teacherReady?'<button class="btn" data-learning-admin="learningPlans">Manage plans</button>':''}</div><div class="weekly-columns"><div><h3>Learn & practise</h3><p>${plan?escapeHtml(plan.topic):'Miss Bell has not published a learning plan for this week yet.'}</p>${plan?`<p>${escapeHtml(plan.practice||'')}</p>${updatedLabel(plan)}`:''}<button class="textbtn public-action" data-public-go="resources">Visit Learning library ↗</button></div><div><h3>Tasks & assessments</h3>${list.map(x=>`<p><b>${escapeHtml(x.title)}</b><br>${x.kind==='test'?'Assessment':'Assignment'} · ${escapeHtml(dateLabel(x.date))}</p>`).join('')||'<p>No published deadlines or tests this week.</p>'}</div></div></section>`;}
function vocabularyWords(){return weekContent('vocabulary')?.words||[];}
function vocabularyCorner(){const set=weekContent('vocabulary');return `<section class="panel vocab-panel"><div class="panelhead"><div><span class="small-caps">A FEW WORDS FOR YOUR WEEK</span><h2>Vocabulary Corner</h2><p>Grade ${classId[0]} · Read, listen, and try a sentence.${set?' Week of '+escapeHtml(dateLabel(set.weekStart)):''}</p></div>${teacherReady?'<button class="btn" data-learning-admin="vocabulary">Manage vocabulary</button>':''}</div><div class="vocab-grid">${vocabularyWords().map(([word,meaning,example],i)=>`<article><div class="vocab-heading"><h3>${escapeHtml(word)}</h3><button class="btn public-action" data-listen="${i}" aria-label="Listen to ${escapeHtml(word)}">Listen ♫</button></div><p>${escapeHtml(meaning)}</p><p class="word-example">“${escapeHtml(example)}”</p></article>`).join('')||'<p class="empty">New words will appear when Miss Bell publishes them.</p>'}</div><p class="form-help vocab-help" id="audioStatus" role="status">Audio uses your device’s English voice, when available.</p></section>`;}
function familyGuide(){return `<details class="panel family-guide"><summary>For families · A little guide to getting started</summary><ol><li><b>Choose a class.</b> Use the class dropdown at the top, then select the correct semester.</li><li><b>Read the news.</b> Announcements contains class reminders and updates from Miss Bell.</li><li><b>Check tasks.</b> Open Assignments for instructions and the due date. Submission records are teacher-only.</li><li><b>Prepare for tests.</b> Assessments shows dates, topics, and what to bring. Calendar includes the weekly learning plan.</li><li><b>Open documents.</b> Use the document link inside a post, when provided. A Google Drive file may require permission from its owner.</li><li><b>Practise together.</b> Explore Vocabulary Corner and the learning activities here. Individual scores are not shown on the public pages.</li></ol><p>No student or parent account is needed. Individual scores and submission records stay private.</p></details>`;}
function initializeAdditions(){
 document.addEventListener('change',e=>{if(e.target.id==='attentionFilter'){attentionFilter=e.target.value;render();}if(e.target.id==='publicationStatus'){const on=e.target.value==='scheduled';$('#publishTimeWrap').hidden=!on;$('#publishAt').required=on;}});
 document.addEventListener('click',e=>{const listen=e.target.closest('[data-listen]');if(listen){const words=vocabularyWords(),entry=words[Number(listen.dataset.listen)],status=$('#audioStatus');if(!entry)return;if(!('speechSynthesis' in window)){status.textContent='Audio is unavailable on this browser. Please read the example aloud together.';return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(entry[0]+'. '+entry[2]);utterance.lang='en-GB';utterance.rate=.8;utterance.onend=()=>{status.textContent='Your turn! Try saying the word and example aloud.';};utterance.onerror=()=>{status.textContent='Audio could not play. Check your device audio or try another browser.';};status.textContent='Playing: '+entry[0];speechSynthesis.speak(utterance);}
 if(e.target.closest('#previewPublication')){const f=new FormData($('#modalForm')),title=f.get('title')||(f.has('words')?'Vocabulary Corner':f.has('practice')?'Weekly Learning Plan':'A note from Miss Bell'),text=f.get('text')||f.get('instructions')||f.get('topic')||f.get('words')||'',box=$('#publicationPreview');let document='';try{document=attachmentLink(readAttachment(f));}catch{document='<p>Add a valid HTTPS document link to include it.</p>';}box.hidden=false;box.innerHTML=`<span class="small-caps">FAMILY PREVIEW · CLASS ${classId} · SEMESTER ${semester}</span><h3>${escapeHtml(title)}</h3><p>${escapeHtml(text)}</p>${f.get('date')?'<p>Test date: '+escapeHtml(f.get('date'))+'</p>':''}${f.get('due')?'<p>Due: '+escapeHtml(f.get('due'))+'</p>':''}${f.get('practice')?'<p>'+escapeHtml(f.get('practice'))+'</p>':''}${f.get('weekStart')?'<p>Week of '+escapeHtml(f.get('weekStart'))+'</p>':''}${f.get('notes')?'<p>'+escapeHtml(f.get('notes'))+'</p>':''}${document}<p class="form-help">Nothing has been published by this preview. Save when you are ready.</p>`;}
 });
 window.addEventListener('bell:render',()=>{if($('#attentionFilter'))$('#attentionFilter').value=attentionFilter;});
 // Refresh teacher previews at the scheduled release time; public sessions use Firestore's time gate.
 let released='';setInterval(()=>{const ids=[...data.announcements,...data.assignments,...data.events,...data.tests].filter(x=>x.status==='scheduled'&&isPublished(x)).map(x=>x.id).sort().join('|');if(ids!==released){released=ids;if(teacherReady&&isPublicView())render();}},15000);
}
initializeAdditions();

function manageLearning(field){if(!canEdit())return;const title=field==='learningPlans'?'Weekly plans':'Vocabulary sets';modal(title,meta(),`<p>Publish classroom content for the selected class and semester. Week starts on Monday.</p><button type="button" class="btn" data-learning-new="${field}">+ Add ${field==='learningPlans'?'weekly plan':'vocabulary set'}</button><div>${classContent(field).sort((a,b)=>b.weekStart.localeCompare(a.weekStart)).map(x=>`<article class="support-card"><h3>Week of ${escapeHtml(x.weekStart)}</h3>${publicationBadge(x)}<p>${escapeHtml(field==='learningPlans'?x.topic:x.words.map(w=>w[0]).join(', '))}</p><button type="button" class="textbtn" data-learning-edit="${field}|${x.id}">Edit</button><button type="button" class="textbtn danger" data-learning-delete="${field}|${x.id}">Unpublish</button></article>`).join('')||'<p>No content yet.</p>'}</div>`,()=>{});$('#modalForm button[type="submit"]').textContent='Done';}
function learningForm(field,id){if(!canEdit())return;const x=classContent(field).find(x=>x.id===id),weekly=field==='learningPlans';$('#modal').close();modal(weekly?'Weekly Learning Plan':'Vocabulary set',meta(),`<label for="weekStart">Week starting (Monday)</label><input id="weekStart" name="weekStart" type="date" required value="${x?.weekStart||weekBounds().start}">${weekly?`<label for="planTopic">What we will learn</label><textarea id="planTopic" name="topic" required maxlength="1000">${escapeHtml(x?.topic||'')}</textarea><label for="planPractice">Practice at home</label><textarea id="planPractice" name="practice" maxlength="1000">${escapeHtml(x?.practice||'')}</textarea>`:`<p>One word per line: word | meaning | example sentence. Up to 20 words.</p><label for="vocabWords">Words, meanings & examples</label><textarea id="vocabWords" name="words" required rows="8" placeholder="book | A set of pages to read. | This is my book.">${escapeHtml((x?.words||[]).map(w=>w.join(' | ')).join('\n'))}</textarea>`}${publicationFields(x)}${x?'':classPicker()}`,f=>{const weekStart=f.get('weekStart');if(new Date(weekStart+'T12:00:00Z').getUTCDay()!==1){toast('Choose a Monday for the start of the week.');return false;}const selected=x?[x.classId]:chosenClasses(f);if(!selected.length){toast('Choose at least one class.');return false;}const fields={weekStart,...readPublication(f)};if(weekly){fields.topic=f.get('topic').trim();fields.practice=f.get('practice').trim();if(!fields.topic){toast('Enter a learning topic.');return false;}}else{fields.words=f.get('words').split(/\r?\n/).filter(x=>x.trim()).map(l=>l.split('|').map(x=>x.trim()));if(!fields.words.length||fields.words.length>20||!fields.words.every(w=>w.length===3&&w.every(v=>v&&v.length<=200))){toast('Use word | meaning | example on every line (up to 20, each field up to 200 characters).');return false;}}data[field]??=[];if(x)Object.assign(x,fields);else for(const c of selected){const existing=data[field].find(y=>y.classId===c&&y.semester===semester&&y.weekStart===weekStart);if(existing)Object.assign(existing,structuredClone(fields));else data[field].push({id:uid(),classId:c,semester,...structuredClone(fields)});}save();render();toast('Updated. Waiting for Firebase save.');});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-learning-admin],[data-learning-new],[data-learning-edit],[data-learning-delete]');if(!b||!canEdit())return;if(b.dataset.learningAdmin)manageLearning(b.dataset.learningAdmin);if(b.dataset.learningNew)learningForm(b.dataset.learningNew);if(b.dataset.learningEdit){const [field,id]=b.dataset.learningEdit.split('|');learningForm(field,id);}if(b.dataset.learningDelete){const [field,id]=b.dataset.learningDelete.split('|');$('#modal').close();modal('Unpublish this learning content?',meta(),'<p>This hides the item from families and keeps it as a private draft. You can publish it again later.</p>',()=>{const item=data[field].find(x=>x.id===id);if(item)Object.assign(item,{status:'draft',publishAt:'',updatedAt:new Date().toISOString()});save();render();});}});
window.addEventListener('bell:render',()=>{if(view==='home'){const box=document.createElement('section');box.className='panel teacher-content-tools';box.innerHTML='<h2>Learning content</h2><p>Write weekly plans and vocabulary for your class.</p><div class="buttons"><button class="btn" id="syncNoticeboard">Sync noticeboard</button><button class="btn" data-learning-admin="learningPlans">Weekly plans</button><button class="btn" data-learning-admin="vocabulary">Vocabulary sets</button></div>';$('#content').prepend(box);}});

document.addEventListener('click',async e=>{if(e.target.closest('#syncNoticeboard')&&canEdit()){save();await flushSave();if(!dirty)toast('Noticeboard synced to Firebase.');}});
